SELECT count(*)
FROM chat_member
WHERE chat_room_id = #{roomId}
  AND employee_id = #{employeeId}
  AND company_id = #{companyId}
  AND left_at IS NULL

SELECT chat_room_id
FROM chat_room
WHERE company_id = #{companyId}
  AND chat_room_id = #{roomId}
FOR UPDATE

SELECT chat_message_id, company_id, chat_room_id,
sender_employee_id, message_type, message_text, attachment_id,
client_message_key, created_at
FROM chat_message
WHERE company_id = #{companyId}
AND chat_room_id = #{roomId}

    AND chat_message_id < #{beforeMessageId}

ORDER BY chat_message_id DESC
FETCH FIRST 50 ROWS ONLY

SELECT chat_message_id, company_id, chat_room_id,
       sender_employee_id, message_type, message_text, attachment_id,
       client_message_key, created_at
FROM chat_message
WHERE company_id = #{companyId}
  AND chat_room_id = #{roomId}
  AND chat_message_id > #{afterMessageId}
ORDER BY chat_message_id ASC
    FETCH FIRST 50 ROWS ONLY

mapper.update:
UPDATE chat_member
SET last_read_message_id =
        GREATEST(NVL(last_read_message_id, 0), #{messageId}),
    updated_at =
        CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
WHERE company_id = #{companyId}
  AND chat_room_id = #{roomId}
  AND employee_id = #{employeeId}
  AND left_at IS NULL
  AND EXISTS (
    SELECT 1
    FROM chat_message msg
    WHERE msg.company_id = #{companyId}
      AND msg.chat_room_id = #{roomId}
      AND msg.chat_message_id = #{messageId}
)

mapper.select:
SELECT chat_room_id
FROM chat_room
WHERE company_id = #{companyId}
  AND room_type = 'ROOM_DIRECT'
  AND direct_employee_low = #{directEmployeeLow}
  AND direct_employee_high = #{directEmployeeHigh}

SELECT chat_message_id, company_id, chat_room_id,
       sender_employee_id, message_type, message_text, attachment_id,
       client_message_key, created_at
FROM chat_message
WHERE company_id = #{companyId}
  AND sender_employee_id = #{senderEmployeeId}
  AND client_message_key = #{clientMessageKey}

SELECT attachment_id
FROM chat_message
WHERE company_id = #{companyId}
  AND chat_room_id = #{roomId}
  AND chat_message_id = #{messageId}
  AND message_type = 'MSG_IMAGE'
  AND deleted_at IS NULL

SELECT employee_id
FROM chat_member
WHERE company_id = #{companyId}
  AND chat_room_id = #{roomId}
  AND left_at IS NULL
